    objectType = {
        name = "sys.usb.device.{i}.interface.{i}.",
        access = "readOnly",
        numEntriesParameter = "InterfacesNumberOfEntries",
        minEntries = 0,
        maxEntries = math.huge,
        parameters = {
            path = {
                access = "readOnly",
                type = "string",
            },
            bInterfaceClassText = {
                access = "readOnly",
                type = "string",
            },
            bInterfaceClass = {
