local function entriesSysBusUsbDevicespartitions(mapping)
    local entries = {}
    local deviceEntries = entriesSysBusUsbDevices()
    for _,device in ipairs(deviceEntries) do
        local dev_list = {}
        local path = syspath .. device .. "/"
        local str = "/usr/bin/find " .. path .. " -name sd*"
        local fp = popen(str)
        if fp then
            for ln in fp:lines() do
                if ln ~= "" then
                    local dev
                    for w in string.gmatch(ln, "[^/]+") do
                        dev = w
                    end
                    if dev then
                        dev_list[#dev_list+1] =  dev
                    end
                end
            end
            fp:close()
        end
        if #dev_list == 1 then
            entries[#entries+1] = device .. "_" .. dev_list[1]
        else
            for _, v in pairs(dev_list) do
                local dev = string.match(v, "sd[a-z][0-9]+")
                if dev then
                    entries[#entries+1] =  device .. "_" .. dev
                end
            end
        end
    end
    return entries
end

local function getMountPoint(key)
    local fp = open("/proc/mounts","r")
    if fp == nil then
        return ""
    end

    local line = fp:read("*a")
    if line then
       local pattern = key .. "%s+([^%s]*)%s"
       local mount = match(line, pattern)
       return mount or ""
    end
    fp:close()
    return ""
end

local function getFileSystem(key)
    local fp = open("/var/state/mounts_ext","r")
    if fp == nil then
        return ""
    end

    local line = fp:read("*a")
    if line then
        local pattern = key .. "%s+[^%s]+%s+([^%s]+)\n"
        local fstype = match(line, pattern)
        return fstype or ""
    end
    fp:close()
    return ""
end

local key_pattern = "(.*)_(.*)"
local function split_partition_key(key)
   return string.match(key, key_pattern)
end

local binding = { config = "minidlna", sectionname = "config", option = "", extended = true }
binding.option = "start_dir"
local start_dir = get_from_uci(binding)
local umountPathTable = {}

--note:mount should not be null
local function getMedia_dirFromMountPoint(mount)
    return mount .. start_dir
end

local function isPathShared(tmpMedia_dir, media_dir)
    if type(media_dir) == "string" and "" ~= media_dir then
        if tmpMedia_dir == media_dir then
            return "1", i
        end
    end

    if type(media_dir) == "table" then
       for i, v in ipairs(media_dir) do
            if v == tmpMedia_dir then
                return "1", i
            end
        end
    end

    return "0", -1
end

local function getPartitions(mapping, paramName, key)
    if paramName == "KeyPath" then
        return key
    end

    local devkey, path = split_partition_key(key)
    if paramName == "path" then
        return path
    elseif paramName == "FileSystem" then
        return getFileSystem(path)
    else
        local mount = getMountPoint(path)
        if mount == "" then
          return mount
        end
        local statvfs_info = posix.statvfs(mount)

        if paramName == "port" then
            return devkey
        elseif paramName == "manufacturer" or paramName == "product" or paramName == "version" then
            return firstline(syspath .. devkey .. "/" .. paramName)
        elseif paramName == "Volume" then
            local volume = match(mount,".*/([^/]*)")
            return volume or ""
        elseif paramName == "TotalSpace" then
            local size = statvfs_info.f_bsize * statvfs_info.f_blocks/(1024*1024*1024)
            size = string.format("%0.2f",size) .. "GB"
            return size
        elseif paramName == "UsedSpace" then
            local size = statvfs_info.f_bsize * (statvfs_info.f_blocks-statvfs_info.f_bfree)/(1024*1024*1024)
            size = string.format("%0.2f",size) .. "GB"
            return size
        elseif paramName == "AvailableSpace" then
            local size = statvfs_info.f_bsize * statvfs_info.f_bfree/(1024*1024*1024)
            size = string.format("%0.2f",size) .. "GB"
            return size
        elseif paramName == "Share" then
            binding.option = "media_dir"
            return isPathShared(getMedia_dirFromMountPoint(mount), get_from_uci(binding))
        elseif paramName == "Stop" then
            local handle = popen("df -h | grep ".. path)
            if handle ~= nil then
                local cmdResult = handle:read("*a")
                handle:close()
                if "" ~= cmdResult then
                    return "0"
                end
            end
            return "1"
        elseif paramName == "Power" then
            return "High Power"
        elseif paramName == "UsbBusy" then
            local tmpCmd = "/usr/bin/fuser " .. mount
            local fp = popen(tmpCmd)
            if fp ~= nil then
                local cmdResult = fp:read("*a")
                if "" ~= cmdResult then
                  return "1"
                end
                fp:close()
            end
            return "0"
        end
    end
    return ""
end

--note:media_dir should not be null
local function getMountPointFromMedia_dir(media_dir)
    local tmpMount = match(media_dir, "(%S+)".. start_dir)
    if nil == tmpMount then
        return match(media_dir, "(%S+)".. "%" .. start_dir)
    else
        return tmpMount
    end
end

local function getDb_dirFromMountPoint(mount)
    return mount .. "/.dlna"
end

--note:db_dir should not be null, minidlna.config.db_dir='$MOUNT_POINT/.dlna'
local function isMountUsedByDb_dir(mount)
    binding.option = "db_dir"
    local db_dir = get_from_uci(binding)
    local tmpDb_dir = getDb_dirFromMountPoint(mount)
    if db_dir == tmpDb_dir then
        return true
    end
    return false
end

local function getDb_dirFromMedia_dir(media_dir)
    return getMountPointFromMedia_dir(media_dir) .. "/.dlna"
end

local function removeMinidlnaRelatedContent(media_dir)
    local db_dir = getDb_dirFromMedia_dir(media_dir)
    os.execute("rm -rf " .. db_dir )
end

--To stop share for minidlna
local function stopSharing(media_dir, mount)
    local db_dir
    local isDb_dirChange = true
    local tmpMedia_dir = getMedia_dirFromMountPoint(mount)
    local isFind, i = isPathShared(tmpMedia_dir, media_dir)

    if "0" == isFind then
        return
    end

    removeMinidlnaRelatedContent(tmpMedia_dir)

    if type(media_dir) == "table" then
        remove(media_dir, i)
        if 0 == #media_dir then
            db_dir = ""
            media_dir = {}
        elseif isMountUsedByDb_dir(mount) then
            db_dir = getDb_dirFromMedia_dir(media_dir[1])
        else
            isDb_dirChange = false
        end
    elseif type(media_dir) == "string" then
        db_dir = ""
        media_dir = {}
    end

    if isDb_dirChange then
        if db_dir ~= "" then
            os.execute("mkdir ".. db_dir)
        end
        binding.option = "db_dir"
        set_on_uci(binding, db_dir, commitapply)
        binding.option = "log_dir"
        set_on_uci(binding, db_dir, commitapply) --log_dir is equal to db_dir
    end
    binding.option = "media_dir"
    set_on_uci(binding, media_dir, commitapply)
end

--To add the conf and restart the minidlna
local function sharePartitionManage(paramValue, path)
    local mount = getMountPoint(path)
    local realValue = paramValue
    if mount == "" then
        return
    end

    --to check whether the usb will be umounted
    local filename = "/tmp/toumountusb"
    local handle, msg = open(filename, "r")
    if handle then
        local data = handle:read("*a")
        if match(data, mount) then
           realValue = "0"
        end
        handle:close()
    end

    binding.option = "media_dir"
    local media_dir = get_from_uci(binding)

    if realValue == "1" then
        --check whether setted before
        local tmpMedia_dir = getMedia_dirFromMountPoint(mount)
        if "1" ==  isPathShared(tmpMedia_dir, media_dir) then
            return
        end

        if type(media_dir) == "table" then
            media_dir[#media_dir + 1] = tmpMedia_dir
            set_on_uci(binding, media_dir, commitapply)
        else
            if type(media_dir) == "string" and "" ~= media_dir then     --Means only one value
                set_on_uci(binding, { media_dir, tmpMedia_dir }, commitapply)
            else                                    --Means no media_dir at all
                binding.option = "media_dir"
                set_on_uci(binding, { tmpMedia_dir }, commitapply)
                local db_dir = getDb_dirFromMountPoint(mount)
                os.execute("mkdir ".. db_dir)
                binding.option = "db_dir"
                set_on_uci(binding, db_dir, commitapply)
                binding.option = "log_dir"
                set_on_uci(binding, db_dir, commitapply)
            end
        end
    else
        stopSharing(media_dir, mount)
    end
    return
end

local function umountUsb(paramValue, path)
    local mount = getMountPoint(path)
    if mount == "" then
       return
    end

    --To reset the minidlna share setting
    binding.option = "media_dir"
    if isPathShared(getMedia_dirFromMountPoint(mount), get_from_uci(binding)) then
        sharePartitionManage("0", path)
    end

    umountPathTable[#umountPathTable + 1] = mount
    return
end

local function setPartitions(mapping, paramName, paramValue, key)
    local _, path = split_partition_key(key)
    if paramName == "Share" then
        return sharePartitionManage(paramValue, path)
    elseif paramName == "Stop" then
        if "0" == paramValue then
           return
        end
        return umountUsb(paramValue, path)
    end
end

local function writeUmountFile(umountPathTable)
    local filename = "/tmp/toumountusb"
    local handle, msg = open(filename, "w")
    if not handle then
        return
    end
    for _, v in ipairs(umountPathTable) do
        handle:write(v)
    end
    handle:close()

    return
end
sys_usb_partition_.entries = entriesSysBusUsbDevicespartitions
sys_usb_partition_.get = getPartitions
sys_usb_partition_.set = setPartitions
sys_usb_partition_.commit = function()
    uci_helper.commit({ config = "minidlna" })
    if #umountPathTable ~= 0 then
        writeUmountFile(umountPathTable)
    end
    umountPathTable = {}
    commitapply:newset("rpc.usb.umount")
end

register(sys_usb_partition_)
